import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Calculate the total for a single line: qty times unitPrice.
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice: subtotal, discount and total.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }}
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    subtotal += total;

    const discountPercent = line.discountPercent ?? 0;
    const lineDiscount = roundCents(total * discountPercent / 100);
    discount += lineDiscount;
  }

  const total = Math.max(0, subtotal - discount);

  return {
    subtotal,
    discount,
    total,
  };
}

function validateDiscountPercent(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) {
    return 0;
  }
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return null;
  }
  return discountPercent;
}

/**
 * Create an invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Validate issueDate format (YYYY-MM-DD) and that it's a real date
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(issueDate)) {
    return fail('DATE_INVALID');
  }

  const [year, month, day] = issueDate.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines is not empty and is an array
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit value wins, otherwise use tier discount
    let discountPercent;
    if ('discountPercent' in line) {
      discountPercent = validateDiscountPercent(line.discountPercent);
      if (discountPercent === null) {
        return fail('DISCOUNT_INVALID');
      }
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier];
    }

    // Get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ customerId: string, status: string, lines: Array<{ sku: string, qty: number, unitPrice: number, vatRate: number, name: string, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 */
export function addLine(invoice, input) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const { sku, qty } = input;

  // Validate qty is positive integer
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Determine discount: explicit value wins, otherwise use tier discount
  let discountPercent;
  if ('discountPercent' in input) {
    discountPercent = validateDiscountPercent(input.discountPercent);
    if (discountPercent === null) {
      return fail('DISCOUNT_INVALID');
    }
  } else {
    discountPercent = TIER_DISCOUNTS[customer.tier];
  }

  // Validate SKU exists in catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((l) => l.sku === sku);

  if (existingLineIndex >= 0) {
    // Update existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }}
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and marking it as issued.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - invoice numbers already used
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

