test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal = 85000, discount = 8500, amountAfterDiscount = 76500, VAT = 76500 × 21 / 100 = 16065
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 16065);
  assert.equal(totals.total, 85000 - 8500 + 16065);
});

test('invoiceTotals returns vat in the result', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 17850);
  assert.equal(totals.total, 102850);
});

test('invoiceTotals sums VAT from multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, unitPrice: 100, vatRate: 9, discountPercent: 0 },
    ],
